package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

const generatorVersion = "1"

const header = "// Code generated by sdks/go/internal/codegen (version " + generatorVersion +
	") from contracts/openapi/server.yaml. DO NOT EDIT.\n\npackage relay\n\n"

func main() {
	contracts := flag.String("contracts", "../../../../contracts", "contracts directory")
	out := flag.String("out", "../..", "output directory of the relay package")
	flag.Parse()
	contractsDir, err := filepath.Abs(*contracts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	l := newLoader()
	g := newGen(l)
	serverFile := filepath.Join(contractsDir, "openapi", "server.yaml")
	root := l.doc(serverFile)
	ops := g.operations(serverFile, root)
	g.breakCycles()
	version := str(get(root, "info"), "version")
	files := map[string][]byte{
		"models_gen.go":     g.emitModels(),
		"operations_gen.go": g.emitOperations(ops),
		"catalog_gen.go":    emitCatalog(l, filepath.Join(contractsDir, "errors.yaml"), version),
	}
	names := make([]string, 0, len(files))
	for name := range files {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		src, err := format.Source(files[name])
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %v\n", name, err)
			_ = os.WriteFile(filepath.Join(*out, name), files[name], 0o644)
			os.Exit(1)
		}
		if err := os.WriteFile(filepath.Join(*out, name), src, 0o644); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
}

func (g *gen) sortedTypes() []string {
	names := make([]string, 0, len(g.types))
	for name := range g.types {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func docLine(name, doc string) string {
	doc = firstSentence(doc)
	if doc == "" {
		return "// " + name + " is generated from the Relay API contract.\n"
	}
	return "// " + name + ": " + doc + "\n"
}

func (g *gen) emitModels() []byte {
	var b bytes.Buffer
	b.WriteString(header)
	for _, name := range g.sortedTypes() {
		d := g.types[name]
		b.WriteString(docLine(name, d.doc))
		if !d.isStruct {
			fmt.Fprintf(&b, "type %s = %s\n\n", name, d.alias.typeExpr())
			continue
		}
		if len(d.fields) == 0 {
			fmt.Fprintf(&b, "type %s struct{}\n\n", name)
			continue
		}
		fmt.Fprintf(&b, "type %s struct {\n", name)
		for _, f := range d.fields {
			typ := f.t.typeExpr()
			if f.pointer {
				typ = "*" + typ
			}
			tag := f.jsonName
			if !f.required {
				tag += ",omitempty"
			}
			fmt.Fprintf(&b, "\t%s %s `json:%s`\n", f.goName, typ, strconv.Quote(tag))
		}
		b.WriteString("}\n\n")
	}
	return b.Bytes()
}

func pathExpr(op operation) string {
	var parts []string
	lit := ""
	for _, seg := range strings.Split(op.path, "/")[1:] {
		lit += "/"
		if strings.HasPrefix(seg, "{") && strings.HasSuffix(seg, "}") {
			name := strings.TrimSuffix(strings.TrimPrefix(seg, "{"), "}")
			parts = append(parts, strconv.Quote(lit))
			lit = ""
			for _, pp := range op.pathParams {
				if pp.name == name {
					parts = append(parts, "pathSegment("+pp.goName+")")
				}
			}
			continue
		}
		lit += seg
	}
	if lit != "" {
		parts = append(parts, strconv.Quote(lit))
	}
	return strings.Join(parts, " + ")
}

func (g *gen) paramField(p param) string {
	switch g.kindOf(p.t) {
	case "slice", "map", "any":
		return p.t.typeExpr()
	}
	if p.required {
		return p.t.typeExpr()
	}
	return "*" + p.t.typeExpr()
}

func (g *gen) emitOperations(ops []operation) []byte {
	var b bytes.Buffer
	usesJSON, usesIter := false, false
	for _, op := range ops {
		if op.resKind == "raw" {
			usesJSON = true
		}
		if op.resKind == "page" {
			usesIter = true
		}
	}
	b.WriteString(header)
	b.WriteString("import (\n\t\"context\"\n")
	if usesJSON {
		b.WriteString("\t\"encoding/json\"\n")
	}
	if usesIter {
		b.WriteString("\t\"iter\"\n")
	}
	b.WriteString(")\n\n")
	for _, op := range ops {
		g.emitOperation(&b, op)
	}
	return b.Bytes()
}

func (g *gen) emitOperation(b *bytes.Buffer, op operation) {
	paramsName := op.paramsName
	if len(op.params) > 0 {
		fmt.Fprintf(b, "// %s holds the query and header parameters of %s.\n", paramsName, op.goName)
		fmt.Fprintf(b, "type %s struct {\n", paramsName)
		for _, p := range op.params {
			fmt.Fprintf(b, "\t%s %s\n", p.goName, g.paramField(p))
		}
		b.WriteString("}\n\n")
	}
	args := []string{"ctx context.Context"}
	callArgs := []string{"ctx"}
	for _, pp := range op.pathParams {
		args = append(args, pp.goName+" "+pp.t.typeExpr())
		callArgs = append(callArgs, pp.goName)
	}
	if op.hasBody {
		args = append(args, "body "+op.bodyType)
		callArgs = append(callArgs, "body")
	}
	if len(op.params) > 0 {
		args = append(args, "params *"+paramsName)
		callArgs = append(callArgs, "params")
	}
	args = append(args, "opts ...RequestOption")
	callArgs = append(callArgs, "opts...")

	var ret string
	switch op.resKind {
	case "page":
		ret = "(*Page[" + op.itemType + "], error)"
	case "raw":
		ret = "(json.RawMessage, error)"
	case "text":
		ret = "(string, error)"
	case "struct":
		ret = "(*" + op.resType + ", error)"
	case "value":
		ret = "(" + op.resType + ", error)"
	default:
		ret = "error"
	}
	summary := ""
	if op.summary != "" {
		summary = ": " + op.summary
	}
	fmt.Fprintf(b, "// %s calls %s %s%s\n", op.goName, op.method, op.path, summary)
	fmt.Fprintf(b, "func (c *Client) %s(%s) %s {\n", op.goName, strings.Join(args, ", "), ret)
	fmt.Fprintf(b, "\tr := newRequest(%q, %s, %t)\n", op.method, pathExpr(op), op.idempotent)
	if op.hasBody {
		fmt.Fprintf(b, "\tif body != nil {\n\t\tr.setBody(body, %q)\n\t}\n", op.bodyCT)
	}
	if len(op.params) > 0 {
		b.WriteString("\tif params != nil {\n")
		for _, p := range op.params {
			g.emitParam(b, p)
		}
		b.WriteString("\t}\n")
	}
	switch op.resKind {
	case "page":
		fmt.Fprintf(b, "\treturn fetchPage[%s](ctx, c, r, opts)\n}\n\n", op.itemType)
		fmt.Fprintf(b, "// %sIter lazily iterates every item of %s across pages.\n", op.goName, op.goName)
		iterArgs := strings.Join(args, ", ")
		fmt.Fprintf(b, "func (c *Client) %sIter(%s) iter.Seq2[%s, error] {\n", op.goName, iterArgs, op.itemType)
		fmt.Fprintf(b, "\treturn pageIter(ctx, func()(*Page[%s], error) {\n\t\treturn c.%s(%s)\n\t})\n}\n\n",
			op.itemType, op.goName, strings.Join(callArgs, ", "))
		return
	case "raw":
		b.WriteString("\tresp, err := c.send(ctx, r, opts)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n")
		b.WriteString("\treturn json.RawMessage(resp.Body), nil\n}\n\n")
	case "text":
		b.WriteString("\tresp, err := c.send(ctx, r, opts)\n\tif err != nil {\n\t\treturn \"\", err\n\t}\n")
		b.WriteString("\treturn string(resp.Body), nil\n}\n\n")
	case "struct":
		b.WriteString("\tresp, err := c.send(ctx, r, opts)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n")
		fmt.Fprintf(b, "\tout := new(%s)\n", op.resType)
		b.WriteString("\tif err := decodeJSON(resp, out); err != nil {\n\t\treturn nil, err\n\t}\n")
		b.WriteString("\treturn out, nil\n}\n\n")
	case "value":
		fmt.Fprintf(b, "\tvar out %s\n", op.resType)
		b.WriteString("\tresp, err := c.send(ctx, r, opts)\n\tif err != nil {\n\t\treturn out, err\n\t}\n")
		b.WriteString("\terr = decodeJSON(resp, &out)\n\treturn out, err\n}\n\n")
	default:
		b.WriteString("\t_, err := c.send(ctx, r, opts)\n\treturn err\n}\n\n")
	}
}

func (g *gen) emitParam(b *bytes.Buffer, p param) {
	field := "params." + p.goName
	add := "r.addQuery"
	if p.in == "header" {
		add = "r.setHeader"
	}
	switch g.kindOf(p.t) {
	case "slice":
		if p.in == "header" {
			fmt.Fprintf(b, "\t\tr.setHeader(%q, joinValues(%s))\n", p.name, field)
		} else {
			fmt.Fprintf(b, "\t\taddQueryList(r, %q, %s, %t)\n", p.name, field, p.explode)
		}
		return
	case "map", "any":
		fmt.Fprintf(b, "\t\tif %s != nil {\n\t\t\t%s(%q, formatValue(%s))\n\t\t}\n", field, add, p.name, field)
		return
	}
	if p.required {
		fmt.Fprintf(b, "\t\t%s(%q, formatValue(%s))\n", add, p.name, field)
		return
	}
	fmt.Fprintf(b, "\t\tif %s != nil {\n\t\t\t%s(%q, formatValue(*%s))\n\t\t}\n", field, add, p.name, field)
}

func emitCatalog(l *loader, errorsFile, version string) []byte {
	root := l.doc(errorsFile)
	var b bytes.Buffer
	b.WriteString(header)
	b.WriteString("// APIVersion is the Relay API version this SDK is pinned to; every request sends it as Relay-Version.\n")
	fmt.Fprintf(&b, "const APIVersion = %q\n\n", version)
	b.WriteString("var errorCatalog = map[string]errorSpec{\n")
	for _, c := range items(get(root, "codes")) {
		status, err := strconv.Atoi(str(c, "status"))
		if err != nil {
			panic(err)
		}
		fmt.Fprintf(&b, "\t%q: {family: %q, status: %d, retryable: %s},\n",
			str(c, "code"), str(c, "family"), status, boolString(str(c, "retryable")))
	}
	b.WriteString("}\n")
	return b.Bytes()
}

func boolString(v string) string {
	if v == "true" {
		return "true"
	}
	return "false"
}
